const getAuditLogHealth = `-- name: GetAuditLogHealth :one
WITH event_volume AS (
  SELECT
    COUNT(*) AS total_events,
    COUNT(*) FILTER (
      WHERE
        created_at >= NOW() - INTERVAL '1 hour'
    ) AS events_last_hour,
    COUNT(*) FILTER (
      WHERE
        created_at >= NOW() - INTERVAL '24 hours'
    ) AS events_last_24h,
    COUNT(*) FILTER (
      WHERE
        created_at >= NOW() - INTERVAL '7 days'
    ) AS events_last_7d
  FROM
    audit_log
  WHERE
    tenant_id = current_tenant_id()
),
risk_metrics AS (
  SELECT
    AVG(risk_score) AS avg_risk_score,
    STDDEV(risk_score) AS stddev_risk_score,
    PERCENTILE_CONT(0.95) WITHIN GROUP (
      ORDER BY
        risk_score
    ) AS p95_risk_score,
    COUNT(*) FILTER (
      WHERE
        risk_score >= 80
    ) AS high_risk_events
  FROM
    audit_log
  WHERE
    tenant_id = current_tenant_id()
    AND created_at >= NOW() - INTERVAL '24 hours'
),
decision_metrics AS (
  SELECT
    COUNT(*) FILTER (
      WHERE
        decision = 'ALLOW'
    ) AS allowed_events,
    COUNT(*) FILTER (
      WHERE
        decision = 'DENY'
    ) AS denied_events,
    ROUND(
      COUNT(*) FILTER (
        WHERE
          decision = 'DENY'
      )::NUMERIC / COUNT(*) * 100,
      2
    ) AS denial_rate_pct
  FROM
    audit_log
  WHERE
    tenant_id = current_tenant_id()
    AND decision IS NOT NULL
    AND created_at >= NOW() - INTERVAL '24 hours'
)
SELECT
  ev.total_events, ev.events_last_hour, ev.events_last_24h, ev.events_last_7d,
  rm.avg_risk_score,
  rm.stddev_risk_score,
  rm.p95_risk_score,
  rm.high_risk_events,
  dm.allowed_events,
  dm.denied_events,
  dm.denial_rate_pct
FROM
  event_volume ev
  CROSS JOIN risk_metrics rm
  CROSS JOIN decision_metrics dm
`

type GetAuditLogHealthRow struct {
	TotalEvents     int64          `json:"total_events"`
	EventsLastHour  int64          `json:"events_last_hour"`
	EventsLast24h   int64          `json:"events_last_24h"`
	EventsLast7d    int64          `json:"events_last_7d"`
	AvgRiskScore    float64        `json:"avg_risk_score"`
	StddevRiskScore float64        `json:"stddev_risk_score"`
	P95RiskScore    float64        `json:"p95_risk_score"`
	HighRiskEvents  int64          `json:"high_risk_events"`
	AllowedEvents   int64          `json:"allowed_events"`
	DeniedEvents    int64          `json:"denied_events"`
	DenialRatePct   pgtype.Numeric `json:"denial_rate_pct"`
}

